"use client";

/* eslint-disable @typescript-eslint/no-explicit-any, react-hooks/set-state-in-effect, @next/next/no-html-link-for-pages, @next/next/no-img-element */

import { FormEvent, PointerEvent as ReactPointerEvent, useCallback, useEffect, useMemo, useRef, useState } from "react";

type View = "home" | "messenger" | "feed" | "calendar" | "documents" | "email" | "board" | "tasks" | "market" | "links" | "settings";
type Row = Record<string, any>;
type Boot = { user: { email: string; name: string; profile: Row }; profiles: Row[]; tasks: Row[]; events: Row[]; threads: Row[]; messages: Row[]; attachments: Row[]; documents: Row[]; links: Row[]; boards: Row[]; board: Row | null; unread: Row[] };

const nav: Array<{ group: string; items: Array<{ id: View; label: string }> }> = [
  { group: "Trabalho", items: [{ id: "home", label: "Visão geral" }, { id: "messenger", label: "Messenger" }, { id: "feed", label: "Notícias" }, { id: "calendar", label: "Calendário" }] },
  { group: "Organização", items: [{ id: "tasks", label: "Tarefas" }, { id: "board", label: "Lousa" }, { id: "documents", label: "Documentos" }, { id: "email", label: "E-mail" }] },
  { group: "Recursos", items: [{ id: "market", label: "Pesquisa de produtos" }, { id: "links", label: "Sites e aplicativos" }, { id: "settings", label: "Personalização" }] },
];

const titles: Record<View, string> = { home: "Visão geral", messenger: "Messenger", feed: "Notícias", calendar: "Calendário", documents: "Documentos", email: "E-mail", board: "Lousas compartilhadas", tasks: "Tarefas", market: "Pesquisa de produtos", links: "Sites e aplicativos", settings: "Personalização" };

function PlannerIcon({name}:{name:View}) {
  const common={width:20,height:20,viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:1.8,strokeLinecap:"round" as const,strokeLinejoin:"round" as const,"aria-hidden":true};
  if(name==="home")return <svg {...common}><path d="m3 11 9-8 9 8"/><path d="M5 10v10h14V10M9 20v-6h6v6"/></svg>;
  if(name==="messenger")return <svg {...common}><path d="M21 11.5a8.5 8.5 0 0 1-9 8.5 9.7 9.7 0 0 1-4-.9L3 21l1.7-4.5A8.5 8.5 0 1 1 21 11.5Z"/><path d="M8 12h.01M12 12h.01M16 12h.01"/></svg>;
  if(name==="feed")return <svg {...common}><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 8h10M7 12h6M7 16h4M16 12h1M15 16h2"/></svg>;
  if(name==="calendar")return <svg {...common}><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01"/></svg>;
  if(name==="tasks")return <svg {...common}><rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 1.5 1.5L12 8M8 15l1.5 1.5L12 14M14 10h2M14 16h2"/></svg>;
  if(name==="board")return <svg {...common}><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M8 8h3v4H8zM14 8h3M14 11h3M8 15h9"/></svg>;
  if(name==="documents")return <svg {...common}><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h4M9 13h6M9 17h6"/></svg>;
  if(name==="email")return <svg {...common}><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></svg>;
  if(name==="market")return <svg {...common}><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5M8 10.5h5M10.5 8v5"/></svg>;
  if(name==="links")return <svg {...common}><path d="M10 13a5 5 0 0 0 7.5.5l2-2a5 5 0 0 0-7-7l-1.2 1.2"/><path d="M14 11a5 5 0 0 0-7.5-.5l-2 2a5 5 0 0 0 7 7l1.2-1.2"/></svg>;
  return <svg {...common}><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/></svg>;
}

async function json(response: Response) {
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "Não foi possível concluir.");
  return data;
}

export default function PlannerApp() {
  const [boot, setBoot] = useState<Boot | null>(null);
  const [view, setView] = useState<View>("home");
  const [loading, setLoading] = useState(true);
  const [unauthorized, setUnauthorized] = useState(false);
  const [menu, setMenu] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [notice, setNotice] = useState("");
  const [searchOpen,setSearchOpen]=useState(false);
  const [globalQuery,setGlobalQuery]=useState("");
  const syncBusy=useRef(false);
  const sync=useCallback(async()=>{if(syncBusy.current)return;syncBusy.current=true;try{const data=await json(await fetch("/api/planner?action=sync",{cache:"no-store"}));setBoot(old=>old?{...old,...data}:old)}catch{}finally{syncBusy.current=false}},[]);
  const markRead=useCallback((thread:string)=>setBoot(old=>old?{...old,unread:old.unread.filter(r=>r.thread_id!==thread)}:old),[]);
  useEffect(()=>{const key=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();setSearchOpen(v=>!v)}if(e.key==="Escape")setSearchOpen(false)};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key)},[]);

  async function load(silent = false) {
    if (!silent) setLoading(true);
    try { setBoot(await json(await fetch("/api/planner", { cache: "no-store" }))); setUnauthorized(false); }
    catch (error: any) { if (/entre|sessão/i.test(error.message)) setUnauthorized(true); else setNotice(error.message); }
    finally { if (!silent) setLoading(false); }
  }
  useEffect(() => { load(); }, []);
  useEffect(()=>{if(view!=="board"||!boot)return;const timer=setInterval(()=>{if(document.visibilityState==="visible")load(true)},30000);return()=>clearInterval(timer)},[view,Boolean(boot)]);
  useEffect(() => { applyPlannerPreferences(); setCollapsed(localStorage.getItem("gwl-planner-sidebar") === "compact"); }, []);
  useEffect(() => {if(!boot)return; const timer=window.setInterval(()=>{if(document.visibilityState==="visible")sync()},15000);return()=>window.clearInterval(timer)}, [Boolean(boot),sync]);

  if (loading && !boot) return <Splash />;
  if (unauthorized || !boot) return <PlannerLogin onSuccess={load} />;

  function open(next: View) { setView(next); setMenu(false); window.scrollTo({ top: 0, behavior: "smooth" }); }
  function toggleSidebar(){setCollapsed(value=>{const next=!value;localStorage.setItem("gwl-planner-sidebar",next?"compact":"expanded");return next})}
  async function logout() { await fetch("/api/ponto-auth", { method: "DELETE" }); setBoot(null); setUnauthorized(true); }
  function flash(message: string) { setNotice(message); window.setTimeout(() => setNotice(""), 3200); }

  const unreadTotal=(boot.unread||[]).reduce((sum,item)=>sum+Number(item.unread_count||0),0);
  const context = { boot, reload: () => load(true), flash, sync, markRead };
  return <main className="planner-shell">
    <aside className={`planner-sidebar ${menu ? "open" : ""} ${collapsed ? "collapsed" : ""}`}>
      <button className="planner-sidebar-close" onClick={() => setMenu(false)} aria-label="Fechar menu">×</button>
      <a className="planner-brand" href="/"><img src="/gwl-planner-logo.png" alt="GWL Planner" /></a>
      <button className="planner-collapse" onClick={toggleSidebar} title={collapsed?"Expandir menu":"Recolher menu"} aria-label={collapsed?"Expandir menu":"Recolher menu"}>{collapsed?"›":"‹"}</button>
      <nav aria-label="Navegação do GWL Planner">
        {nav.map(section => <section key={section.group}><small>{section.group}</small>{section.items.map(item => <button key={item.id} title={collapsed?item.label:undefined} className={view === item.id ? "active" : ""} onClick={() => open(item.id)}><i><PlannerIcon name={item.id}/></i><span>{item.label}</span>{item.id === "messenger" && unreadTotal>0 && <b>{unreadTotal>99?"99+":unreadTotal}</b>}</button>)}</section>)}
      </nav>
      <a className="planner-back" href="/">← Voltar ao GWL NEXO</a>
      <div className="planner-profile"><span>{initials(boot.user.name)}</span><div><strong>{boot.user.name}</strong><small>{taskRoleName(taskRole(boot.user.profile))}</small></div><button onClick={logout} title="Sair">↗</button></div>
    </aside>
    <section className={`planner-main ${collapsed?"sidebar-compact":""}`}>
      <header className="planner-topbar"><button className="planner-menu" onClick={() => setMenu(true)}>☰</button><div><span>GWL Planner</span><b>/</b><strong>{titles[view]}</strong></div><label><span>⌕</span><input placeholder="Buscar no Planner · Ctrl K" value={globalQuery} onFocus={()=>setSearchOpen(true)} onChange={e=>{setGlobalQuery(e.target.value);setSearchOpen(true)}} /></label><button className="top-notifications" onClick={()=>open("messenger")} aria-label={`${unreadTotal} mensagens não lidas`} title="Notificações do Messenger"><PlannerIcon name="messenger"/>{unreadTotal>0&&<b>{unreadTotal>99?"99+":unreadTotal}</b>}</button><time>{new Intl.DateTimeFormat("pt-BR", { weekday: "short", day: "2-digit", month: "short" }).format(new Date())}</time><button className="top-avatar" onClick={() => open("settings")}>{initials(boot.user.name)}</button></header>
      <div className="planner-content"><FocusTimer visible={view==="home"||view==="tasks"} tasks={boot.tasks.filter(t=>ownExecution(t,boot.user.email))}/>
        {view === "home" && <Home ctx={context} open={open} />}
        {view === "messenger" && <Messenger ctx={context} />}
        {view === "feed" && <News />}
        {view === "calendar" && <Calendar ctx={context} />}
        {view === "documents" && <Documents ctx={context} />}
        {view === "email" && <EmailHub />}
        {view === "board" && <Whiteboard ctx={context} />}
        {view === "tasks" && <Tasks ctx={context} />}
        {view === "market" && <Market ctx={context} />}
        {view === "links" && <Links ctx={context} />}
        {view === "settings" && <Settings user={boot.user} flash={flash} />}
      </div>
    </section>
    {searchOpen&&<GlobalSearch ctx={context} query={globalQuery} setQuery={setGlobalQuery} open={open} close={()=>setSearchOpen(false)}/>}
    {notice && <div className="planner-toast" role="status">{notice}</div>}
  </main>;
}

function Splash() { return <main className="planner-splash"><img src="/gwl-planner-logo.png" alt="GWL Planner" /><span /><p>Preparando seu espaço de trabalho...</p></main>; }

function PlannerLogin({ onSuccess }: { onSuccess: () => Promise<void> }) {
  const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError(""); const form = new FormData(event.currentTarget);
    try { await json(await fetch("/api/ponto-auth", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "login", accessType: "planner", email: form.get("email"), password: form.get("password"), remember: Boolean(form.get("remember")) }) })); await onSuccess(); }
    catch (e: any) { setError(e.message); } finally { setBusy(false); }
  }
  return <main className="planner-login"><a href="/" className="login-back">← Voltar ao portal</a><section><div className="login-art"><img src="/gwl-planner-logo.png" alt="GWL Planner" /><h1>Seu trabalho,<br /><em>todo conectado.</em></h1><p>Comunicação, organização e produtividade em um único ambiente.</p><div className="login-pills"><i>✓ Tarefas</i><i>◫ Documentos</i><i>◌ Equipe</i></div></div><form onSubmit={submit}><small>ACESSO CORPORATIVO</small><h2>Entrar no GWL Planner</h2><p>Use seu acesso corporativo do GWL NEXO.</p><label>E-mail ou usuário<input name="email" type="text" autoComplete="username" required placeholder="seuemail@empresa.com.br" /></label><label>Senha<input name="password" type="password" autoComplete="current-password" required placeholder="Digite sua senha" /></label><label className="remember"><input name="remember" type="checkbox" /> Manter conectado neste dispositivo</label>{error && <div className="login-error">{error}</div>}<button disabled={busy}>{busy ? "Entrando..." : "Entrar no Planner →"}</button><div className="register-link"><span>Ainda não tem acesso?</span><a href="/planner/cadastro">Criar minha conta</a></div><footer>Acesso protegido e vinculado ao seu perfil corporativo.</footer></form></section></main>;
}

function Home({ ctx, open }: { ctx: Ctx; open: (view: View) => void }) {
  const pending = ctx.boot.tasks.filter(t => t.status !== "concluida" && ownExecution(t,ctx.boot.user.email)).sort((a,b)=>String(a.due_date||"9999").localeCompare(String(b.due_date||"9999")));
  const today = new Date().toLocaleDateString("sv-SE");
  const todayEvents = ctx.boot.events.filter(e => e.event_date === today);
  const upcoming = ctx.boot.events.filter(e => e.event_date >= today).slice(0, 5);
  const recentMessages = [...ctx.boot.messages].slice(-4).reverse();
  const recentDocuments = ctx.boot.documents.slice(0, 5);
  const boardCards = (ctx.boot.boards || []).flatMap(board => readBoardPayload(board.payload).cards);
  const boardOpen = boardCards.filter(card => card.status !== "done").length;
  const quickTools = [
    { id: "messenger", icon: "◌", label: "Messenger", color: "cyan" }, { id: "calendar", icon: "▦", label: "Calendário", color: "purple" },
    { id: "documents", icon: "▤", label: "Documentos", color: "orange" }, { id: "tasks", icon: "✓", label: "Tarefas", color: "green" },
    { id: "board", icon: "◇", label: "Lousa", color: "pink" }, { id: "feed", icon: "◫", label: "Notícias", color: "blue" },
    { id: "market", icon: "⌕", label: "Produtos", color: "orange" }, { id: "links", icon: "↗", label: "Sites e apps", color: "cyan" },
    { id: "settings", icon: "⚙", label: "Personalizar", color: "purple" },
  ];
  return <div className="overview-dashboard"><PageTitle eyebrow="CENTRAL DE TRABALHO" title={`${new Date().getHours()<12?"Bom dia":new Date().getHours()<18?"Boa tarde":"Boa noite"}, ${firstName(ctx.boot.user.name)}!`} text={new Intl.DateTimeFormat("pt-BR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" }).format(new Date())} action={<button className="primary" onClick={() => open("tasks")}>＋ Nova tarefa</button>} />
    <section className="planner-metrics"><article className="metric-blue"><span>✓</span><div><small>TAREFAS PENDENTES</small><strong>{pending.length}</strong><p>{pending.length ? "Prioridades para organizar" : "Tudo concluído"}</p></div></article><article className="metric-purple"><span>▦</span><div><small>EVENTOS HOJE</small><strong>{todayEvents.length}</strong><p>{todayEvents.length ? "Compromissos na agenda" : "Agenda livre"}</p></div></article><article className="metric-orange"><span>▤</span><div><small>DOCUMENTOS</small><strong>{ctx.boot.documents.length}</strong><p>Arquivos no seu espaço</p></div></article><article className="metric-green"><span>◌</span><div><small>CONVERSAS</small><strong>{ctx.boot.threads.length}</strong><p>{recentMessages.length} mensagens recentes</p></div></article></section>
    <div className="planner-day-strip"><button onClick={()=>open("tasks")}><strong>{pending.filter(t=>t.due_date&&t.due_date<today).length}</strong><span>Tarefas atrasadas</span></button><button onClick={()=>open("tasks")}><strong>{ctx.boot.tasks.filter(t=>t.visibility==="public"&&!t.assignee_email&&t.status==="pendente").length}</strong><span>Disponíveis para assumir</span></button><button onClick={()=>open("messenger")}><strong>{ctx.boot.unread.reduce((n,r)=>n+Number(r.unread_count||0),0)}</strong><span>Mensagens não lidas</span></button></div><section className="overview-grid">
      <article className="panel overview-agenda"><header><div><small>AGENDA DE HOJE</small><h2>Próximos compromissos</h2></div><button onClick={() => open("calendar")}>Ver calendário →</button></header><div>{(todayEvents.length ? todayEvents : upcoming).map(event => <button key={event.id} onClick={() => open("calendar")}><time>{event.event_time || new Date(`${event.event_date}T12:00:00`).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" })}</time><i style={{ background: event.color }} /><span><strong>{event.emoji} {event.title}</strong><small>{event.event_date === today ? "Hoje" : humanDate(event.event_date)}{event.notes ? ` • ${event.notes}` : ""}</small></span></button>)}{!(todayEvents.length || upcoming.length) && <Empty icon="▦" title="Agenda livre" text="Seus compromissos aparecerão aqui." />}</div></article>
      <article className="panel overview-tasks"><header><div><small>MINHAS TAREFAS</small><h2>Prioridades</h2></div><button onClick={() => open("tasks")}>Ver todas →</button></header>{pending.slice(0, 5).map(task => <div className="mini-task" key={task.id}><button className="overview-task-check" aria-label={`Concluir tarefa ${task.title}`} onClick={() => act(ctx, { action: "task.toggle", id: task.id })}>✓</button><span><strong>{task.title}</strong><small>{task.due_date ? humanDate(task.due_date) : "Sem prazo"}</small></span><i className={`priority-label ${task.priority}`}>{urgencyName(task.priority)}</i></div>)}{!pending.length && <Empty icon="✓" title="Tudo em dia" text="Suas novas tarefas aparecerão aqui." />}</article>
      <article className="panel quick-panel overview-quick"><header><div><small>ACESSO RÁPIDO</small><h2>Todos os recursos</h2></div></header><div>{quickTools.map(item => <button key={item.id} onClick={() => open(item.id as View)}><i className={item.color}><PlannerIcon name={item.id as View}/></i><span>{item.label}</span></button>)}</div></article>

      <article className="panel overview-messages"><header><div><small>MESSAGENS RECENTES</small><h2>Conversas da equipe</h2></div><button onClick={() => open("messenger")}>Ver todas →</button></header><div>{recentMessages.map(message => {const count=ctx.boot.attachments.filter(file=>file.message_id===message.id).length;return <button key={message.id} onClick={() => open("messenger")}><span>{initials(message.sender_name || message.sender_email)}</span><div><strong>{message.sender_name || message.sender_email}</strong><small>{message.body || (count?`📎 ${count} arquivo(s) compartilhado(s)`:"Mensagem enviada")}</small></div><time>{shortTime(message.created_at)}</time></button>})}{!recentMessages.length && <Empty icon="◌" title="Sem mensagens" text="As conversas recentes aparecerão aqui." />}</div></article>
      <article className="panel overview-documents"><header><div><small>DOCUMENTOS RECENTES</small><h2>Arquivos atualizados</h2></div><button onClick={() => open("documents")}>Ver todos →</button></header><div>{recentDocuments.map(doc => <button key={doc.id} onClick={() => open("documents")}><span className={`file-kind ${fileKind(doc.file_name)}`}>{fileKind(doc.file_name).toUpperCase()}</span><div><strong>{doc.file_name}</strong><small>{formatBytes(doc.size)} • {humanDate(doc.updated_at?.slice(0, 10))}</small></div></button>)}{!recentDocuments.length && <Empty icon="▤" title="Sem documentos" text="Envie arquivos para vê-los aqui." />}</div></article>
      <DashboardNews open={open} />

      <article className="panel overview-board"><header><div><small>LOUSAS COMPARTILHADAS</small><h2>Tarefas em conjunto</h2></div><button onClick={() => open("board")}>Abrir lousas →</button></header><div className="board-summary"><span>◇</span><div><strong>{boardOpen} tarefa(s) em aberto</strong><small>{ctx.boot.boards?.length ? `${ctx.boot.boards.length} lousa(s) disponível(is) • ${boardCards.filter(card => card.status === "done").length} concluída(s)` : "Crie sua lousa e compartilhe tarefas com usuários permitidos."}</small></div></div><button className="dashboard-action" onClick={() => open("board")}>Organizar tarefas compartilhadas</button></article>
      <article className="panel overview-resources"><header><div><small>RECURSOS</small><h2>Compras e aplicativos</h2></div></header><button onClick={() => open("market")}><span>⌕</span><div><strong>Pesquisar produtos</strong><small>Compare ofertas e abra anúncios das lojas.</small></div><b>→</b></button><button onClick={() => open("links")}><span>↗</span><div><strong>Sites e aplicativos</strong><small>{ctx.boot.links.length} atalho(s) cadastrado(s).</small></div><b>→</b></button><button onClick={() => open("settings")}><span>⚙</span><div><strong>Personalizar painel</strong><small>Temas, cores, densidade e formato.</small></div><b>→</b></button></article>
    </section>
  </div>;
}

let recentNews:Row|null=null;
let newsPending:Promise<Row>|null=null;
function getNews(force=false):Promise<Row>{
  if(!force&&recentNews&&Date.now()-recentNews.loadedAt<120000)return Promise.resolve(recentNews);
  if(newsPending)return newsPending;
  newsPending=fetch("/api/planner?action=news").then(json).then(data=>{const value:Row={...data,loadedAt:Date.now()};recentNews=value;return value}).finally(()=>{newsPending=null});
  return newsPending!;
}
function DashboardNews({ open }: { open: (view: View) => void }) {
  const [items, setItems] = useState<Row[]>(recentNews?.news?.slice(0,4)||[]);
  const [finished,setFinished]=useState(false);
  useEffect(() => { getNews().then(data => setItems((data.news || []).slice(0, 4))).catch(() => setItems([])).finally(()=>setFinished(true)); }, []);
  return <article className="panel overview-news"><header><div><small>ÚLTIMAS NOTÍCIAS</small><h2>Atualidade em fontes confiáveis</h2></div><button onClick={() => open("feed")}>Ver todas →</button></header><div>{items.map(item => <a href={item.link} target="_blank" rel="noreferrer" key={item.id}><span>{item.category?.slice(0, 1) || "N"}</span><div><strong>{item.title}</strong><small>{item.source} • {item.publishedAt ? relativeTime(item.publishedAt) : "recente"}</small></div></a>)}{!items.length && <p className="dashboard-loading">{finished?"Fontes temporariamente indisponíveis. Abra Notícias para tentar novamente.":"Buscando as notícias mais recentes..."}</p>}</div></article>;
}

type Ctx = { boot: Boot; reload: () => Promise<void>; flash: (m: string) => void; sync:()=>Promise<void>; markRead:(thread:string)=>void };
async function act(ctx: Ctx, payload: Row) { try { await json(await fetch("/api/planner", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) })); await ctx.reload(); ctx.flash("Alteração salva."); return true; } catch (e: any) { ctx.flash(e.message); return false; } }

function Messenger({ ctx }: { ctx: Ctx }) {
  const [thread,setThread]=useState(ctx.boot.threads[0]?.id||"general");
  const [query,setQuery]=useState("");const [find,setFind]=useState("");const [group,setGroup]=useState(false);
  const [messages,setMessages]=useState<Row[]>([]);const [attachments,setAttachments]=useState<Row[]>([]);
  const [files,setFiles]=useState<File[]>([]);const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(true);const [more,setMore]=useState(false);const [error,setError]=useState("");
  const fileInput=useRef<HTMLInputElement>(null);const panel=useRef<HTMLDivElement>(null);
  const cursor=useRef(0);const first=useRef(0);const read=useRef(0);const fetching=useRef(false);const request=useRef<AbortController|null>(null);const generation=useRef(0);
  const active=ctx.boot.threads.find(t=>t.id===thread);
  async function refresh(older=false){
    if(fetching.current)return;fetching.current=true;const version=generation.current;const controller=new AbortController();request.current=controller;
    const scroll=panel.current;const nearBottom=!scroll||scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<120;
    try{const suffix=older?`&before=${first.current}`:cursor.current?`&after=${cursor.current}`:"";
      const data=await json(await fetch(`/api/planner?action=messages&thread=${encodeURIComponent(thread)}${suffix}`,{signal:controller.signal,cache:"no-store"}));
      if(version!==generation.current)return;setError("");
      const incoming=data.messages||[];
      setMessages(old=>[...new Map([...old,...incoming].map(m=>[m.id,m])).values()].sort((a,b)=>a.id-b.id));
      setAttachments(old=>[...new Map([...old,...(data.attachments||[])].map(a=>[a.id,a])).values()]);
      if(older||!cursor.current)setMore(data.hasMore);
      if(incoming.length){first.current=Math.min(first.current||Infinity,...incoming.map((m:Row)=>m.id));cursor.current=Math.max(cursor.current,...incoming.map((m:Row)=>m.id));}
      if(!older&&nearBottom)requestAnimationFrame(()=>{if(panel.current)panel.current.scrollTop=panel.current.scrollHeight});
      if(!older&&cursor.current>read.current&&document.visibilityState==="visible"){
        const lastId=cursor.current;await json(await fetch("/api/planner",{method:"POST",headers:{"content-type":"application/json"},signal:controller.signal,body:JSON.stringify({action:"message.read",threadId:thread,lastId})}));
        if(version===generation.current){read.current=lastId;ctx.markRead(thread);}
      }
    }catch(e:any){if(e.name!=="AbortError"&&version===generation.current)setError(e.message)}finally{if(version===generation.current){setLoading(false);fetching.current=false}}
  }
  useEffect(()=>{generation.current++;request.current?.abort();fetching.current=false;cursor.current=0;first.current=0;read.current=0;setMessages([]);setAttachments([]);setLoading(true);setMore(false);setFind("");refresh();
    const timer=setInterval(()=>{if(document.visibilityState==="visible")refresh()},6000);
    const visible=()=>{if(document.visibilityState==="visible")refresh()};document.addEventListener("visibilitychange",visible);
    return()=>{generation.current++;request.current?.abort();fetching.current=false;clearInterval(timer);document.removeEventListener("visibilitychange",visible)};
  },[thread]);
  async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const input=e.currentTarget.elements.namedItem("message") as HTMLInputElement;if(!input.value.trim()&&!files.length)return;setBusy(true);
    const data=new FormData();data.set("action","message.send");data.set("threadId",thread);data.set("message",input.value);files.forEach(f=>data.append("files",f));
    try{await json(await fetch("/api/planner",{method:"POST",body:data}));input.value="";setFiles([]);if(fileInput.current)fileInput.current.value="";await refresh();ctx.sync();}catch(e:any){ctx.flash(e.message)}finally{setBusy(false)}
  }
  const visible=messages.filter(m=>`${m.body} ${m.sender_name}`.toLowerCase().includes(find.toLowerCase()));
  return <><PageTitle eyebrow="EQUIPE" title="Messenger" text="Mensagens, arquivos e histórico da conversa." action={<button className="primary" onClick={()=>setGroup(true)}>＋ Criar grupo</button>}/>
    <section className="messenger-layout panel"><aside><label>⌕<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar conversa..."/></label>{ctx.boot.threads.filter(t=>t.title.toLowerCase().includes(query.toLowerCase())).map(t=><button disabled={busy} className={t.id===thread?"active":""} key={t.id} onClick={()=>{setThread(t.id);setFiles([])}}><span>{initials(t.title)}</span><div><strong>{t.title}</strong><small>{t.kind==="general"?"Canal geral":"Grupo privado"}</small></div>{Number(ctx.boot.unread.find(u=>u.thread_id===t.id)?.unread_count)>0&&<em className="thread-unread">{ctx.boot.unread.find(u=>u.thread_id===t.id)?.unread_count}</em>}</button>)}</aside>
    <main><header><span>{initials(active?.title||"GW")}</span><div><strong>{active?.title}</strong><small>Atualização automática</small></div><input className="message-search" aria-label="Buscar no histórico carregado" placeholder="Buscar no histórico carregado" value={find} onChange={e=>setFind(e.target.value)}/></header>
    {error&&<div className="planner-inline-error">{error}<button onClick={()=>refresh()}>Tentar novamente</button></div>}
    <div className="messages" ref={panel}>{more&&<button className="history-button" onClick={()=>refresh(true)}>Carregar anteriores</button>}{loading&&<p role="status">Carregando conversa...</p>}{visible.map(m=><article className={m.sender_email===ctx.boot.user.email?"mine":""} key={m.id}><div><b>{m.sender_name}</b>{m.body&&<p>{m.body}</p>}<div className="message-attachments">{attachments.filter(a=>a.message_id===m.id).map(file=><MessageAttachment key={file.id} file={file}/>)}</div><time>{dateTime(m.created_at)}</time></div></article>)}{!loading&&!visible.length&&<Empty icon="◌" title={find?"Nenhuma mensagem encontrada":"Comece a conversa"} text={find?"Carregue mais histórico ou ajuste a pesquisa.":"Envie uma mensagem ou um arquivo."}/>}</div>
    <form className="message-composer" onSubmit={send}>{files.length>0&&<div className="selected-attachments">{files.map((f,i)=><span key={i}><small>{f.name}</small><button type="button" onClick={()=>setFiles(old=>old.filter((_,n)=>n!==i))}>×</button></span>)}</div>}<div className="composer-row"><input hidden ref={fileInput} type="file" multiple onChange={e=>{const next=Array.from(e.target.files||[]);if(next.length>5||next.some(f=>f.size>10*1024*1024)){ctx.flash("Até 5 arquivos, com no máximo 10 MB cada.");return}setFiles(next)}}/><button type="button" aria-label="Anexar arquivo" onClick={()=>fileInput.current?.click()}>＋</button><input name="message" placeholder="Escreva uma mensagem..." autoComplete="off"/><button disabled={busy||loading} aria-label="Enviar mensagem">{busy?"…":"➤"}</button></div></form></main></section>{group&&<GroupModal ctx={ctx} close={()=>setGroup(false)}/>}</>;
}

function MessageAttachment({file}:{file:Row}){const href=`/api/planner?action=message.attachment&id=${file.id}`;const image=String(file.content_type||"").startsWith("image/");return image?<a className="message-image" href={href} target="_blank" rel="noreferrer"><img src={href} alt={file.file_name} loading="lazy" decoding="async"/><span>{file.file_name}</span></a>:<a className="message-file" href={href} target="_blank" rel="noreferrer"><b>{fileKind(file.file_name).toUpperCase()}</b><span><strong>{file.file_name}</strong><small>{formatBytes(Number(file.size||0))}</small></span><i>↓</i></a>}

function GroupModal({ ctx, close }: { ctx: Ctx; close: () => void }) {
  const [selected, setSelected] = useState<string[]>([]); const [query, setQuery] = useState("");
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); await act(ctx, { action: "group.create", title: form.get("title"), members: selected }); close(); }
  return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><header><div><small>NOVA CONVERSA</small><h2>Criar grupo</h2></div><button type="button" onClick={close}>×</button></header><label>Nome do grupo<input name="title" required placeholder="Ex.: Administrativo, Contrato HGG..." /></label><label>Adicionar pessoas<input value={query} onChange={e => setQuery(e.target.value)} placeholder="Pesquisar usuário..." /></label><div className="member-list">{ctx.boot.profiles.filter(p => `${p.name} ${p.email}`.toLowerCase().includes(query.toLowerCase())).slice(0, 20).map(p => <label key={p.email}><input type="checkbox" checked={selected.includes(p.email)} onChange={() => setSelected(v => v.includes(p.email) ? v.filter(x => x !== p.email) : [...v, p.email])} /><span>{initials(p.name)}</span><div><strong>{p.name || p.email}</strong><small>{p.role}</small></div></label>)}</div><footer><button type="button" onClick={close}>Cancelar</button><button className="primary">Criar grupo</button></footer></form></div>;
}

function News() {
  const [news, setNews] = useState<Row[]>(recentNews?.news||[]); const [loading, setLoading] = useState(!recentNews); const [updated, setUpdated] = useState(recentNews?.updatedAt||""); const [filter, setFilter] = useState("Todas"); const [error, setError] = useState("");
  async function load(force=false) { setLoading(true); setError(""); try { const data = await getNews(force); setNews(data.news || []); setUpdated(data.updatedAt); } catch (e:any) { setError(e.message); } finally { setLoading(false); } }
  useEffect(() => { load();const timer=setInterval(()=>{if(document.visibilityState==="visible")load()},120000);return()=>clearInterval(timer); }, []);
  const available = new Set(news.map(item => item.category).filter(Boolean));
  const categories = ["Todas", ...["Goiás","Mundo","Brasil"].filter(category=>available.has(category)), ...Array.from(available).filter(category=>!["Goiás","Mundo","Brasil"].includes(category))];
  const visible = filter === "Todas" ? news : news.filter(item => item.category === filter);
  return <><PageTitle eyebrow="ÚLTIMAS 24 HORAS" title="Notícias importantes agora" text="Fatos recentes de Goiânia e Goiás, junto aos acontecimentos mundiais de maior impacto. Conteúdos antigos são removidos automaticamente." action={<button disabled={loading} onClick={()=>load(true)}>{loading?"Atualizando...":"↻ Atualizar notícias"}</button>} />
    <div className="news-toolbar"><div className="filter-tabs">{categories.map(category => <button className={filter===category?"active":""} onClick={()=>setFilter(category)} key={category}>{category}</button>)}</div>{updated && <span>Busca realizada em {dateTime(updated)}</span>}</div>
    {error && <div className="planner-inline-error">{error}</div>}
    <section className="news-grid">{loading && !news.length ? [1,2,3,4,5,6].map(i => <article className="news-skeleton" key={i} />) : visible.map((item, i) => <a href={item.link} target="_blank" rel="noreferrer" key={item.id} className={`news-card ${i === 0 && filter === "Todas" ? "featured" : ""}`}><div><span className="news-source">{item.source}</span><small>{item.category || "Atualidade"}</small><span className="news-freshness">{item.freshness || "Recente"}</span><h2>{item.title}</h2><p>{new Date(item.publishedAt).toLocaleString("pt-BR",{dateStyle:"short",timeStyle:"short"})}</p></div><strong>Abrir no site da fonte ↗</strong></a>)}</section>
    {!loading && !visible.length && <section className="panel"><Empty icon="◫" title="Nenhuma notícia disponível" text="Tente atualizar novamente em alguns instantes." /></section>}</>;
}

const taskRole=(profile:Row)=>profile.role==="Administrador"?"administrador":profile.planner_role||"colaborador";
const taskRoleName=(role:string)=>(({administrador:"Administrador",gerente:"Gerente",colaborador:"Colaborador"} as Record<string,string>)[role]||"Colaborador");
const ownExecution=(t:Row,email:string)=>t.visibility==="personal"||!t.visibility?t.owner_email===email:t.assignee_email===email;
const urgencyName=(p:string)=>(({baixa:"Baixa",media:"Média",alta:"Alta",urgente:"Urgente"} as Record<string,string>)[p]||p);
function Tasks({ctx}:{ctx:Ctx}){
  const role=taskRole(ctx.boot.user.profile),manager=role!=="colaborador";
  const [tab,setTab]=useState("mine");const [filter,setFilter]=useState("pending");const [query,setQuery]=useState("");const [show,setShow]=useState(false);const [editing,setEditing]=useState<Row|null>(null);const [busy,setBusy]=useState<number|null>(null);
  const today=new Date().toLocaleDateString("sv-SE"),email=ctx.boot.user.email;
  const mine=ctx.boot.tasks.filter(t=>ownExecution(t,email));
  const available=ctx.boot.tasks.filter(t=>t.visibility==="public"&&!t.assignee_email&&t.status==="pendente");
  const rows=(tab==="mine"?mine:tab==="available"?available:ctx.boot.tasks.filter(t=>t.visibility==="public")).filter(t=>`${t.title} ${t.notes} ${t.assignee_name}`.toLowerCase().includes(query.toLowerCase())&&(filter==="all"||filter==="done"?filter==="all"||t.status==="concluida":t.status!=="concluida"&&(filter==="today"?t.due_date===today:filter==="late"?t.due_date&&t.due_date<today:true))).sort((a,b)=>({urgente:0,alta:1,media:2,baixa:3}[a.priority as "alta"]??2)-({urgente:0,alta:1,media:2,baixa:3}[b.priority as "alta"]??2)||String(a.due_date||"9999").localeCompare(String(b.due_date||"9999")));
  async function execute(t:Row,action:string,status?:string){if(busy!==null)return;setBusy(t.id);try{await act(ctx,{action,id:t.id,status});await ctx.sync()}finally{setBusy(null)}}
  return <><PageTitle eyebrow={taskRoleName(role).toUpperCase()} title="Tarefas" text={manager?"Defina o trabalho, o prazo e a urgência. Escolha um destinatário ou publique para a equipe.":"Organize suas tarefas, receba demandas e assuma trabalhos disponíveis."} action={<button className="primary" onClick={()=>setShow(true)}>＋ {manager?"Criar ou delegar tarefa":"Nova tarefa pessoal"}</button>}/>
    <div className="task-summary"><span><strong>{mine.filter(t=>t.status!=="concluida").length}</strong> sob minha responsabilidade</span><span><strong>{available.length}</strong> disponíveis para assumir</span></div>
    <div className="filter-tabs" aria-label="Tipo de tarefa">{[["mine","Minhas tarefas"],["available","Disponíveis"],["public","Mural público"],...(role==="administrador"?[["roles","Equipe e perfis"]]:[])].map(([id,label])=><button aria-pressed={tab===id} className={tab===id?"active":""} key={id} onClick={()=>setTab(id)}>{label}</button>)}</div>
    {tab==="roles"&&role==="administrador"?<PlannerRoles ctx={ctx}/>:<><div className="delegation-filters"><input aria-label="Buscar tarefas" placeholder="Buscar tarefa ou responsável..." value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Filtrar por situação" value={filter} onChange={e=>setFilter(e.target.value)}><option value="pending">Em aberto</option><option value="today">Prazo hoje</option><option value="late">Atrasadas</option><option value="done">Concluídas</option><option value="all">Todas as situações</option></select><button onClick={()=>ctx.sync()}>Atualizar</button></div><section className="delegated-tasks">{rows.map(t=>{
      const assigned=Boolean(t.assignee_email),canRun=ownExecution(t,email),canEdit=t.owner_email===email&&t.visibility!=="assigned"&&(t.visibility!=="public"||manager);
      return <article className={"panel delegated-task "+(t.status==="concluida"?"task-done":"")} key={t.id}><header><span className={"task-urgency "+t.priority}>{urgencyName(t.priority)}</span><span>{t.visibility==="public"?"Pública · visível para todos":t.visibility==="assigned"?"Direcionada · somente você":"Pessoal · somente você"}</span></header><h2>{t.title}</h2>{t.notes&&<p className="task-description">{t.notes}</p>}<dl><div><dt>Prazo</dt><dd>{t.due_date?humanDate(t.due_date):"Sem prazo"}{t.due_time?" às "+t.due_time:""}</dd></div>{Number(t.estimated_minutes)>0&&<div><dt>Tempo estimado</dt><dd>{t.estimated_minutes} min</dd></div>}<div><dt>Criada por</dt><dd>{t.creator_name||t.owner_email}</dd></div></dl><div className="task-execution"><strong>{t.status==="concluida"?"Concluída":t.status==="em_andamento"?"Em andamento":assigned?"Aguardando início":t.visibility==="public"?"Disponível para assumir":"Pendente"}</strong>{assigned&&<span>Responsável: {t.assignee_name||t.assignee_email}</span>}</div><footer>{t.visibility==="public"&&!assigned&&t.status==="pendente"&&<button className="primary" disabled={busy!==null} onClick={()=>execute(t,"task.claim")}>{busy===t.id?"Assumindo...":"Assumir tarefa"}</button>}{canRun&&<>{t.status==="pendente"&&<button disabled={busy!==null} onClick={()=>execute(t,"task.status","em_andamento")}>Iniciar</button>}<button disabled={busy!==null} onClick={()=>execute(t,"task.status",t.status==="concluida"?"pendente":"concluida")}>{t.status==="concluida"?"Reabrir":"Concluir"}</button></>}{canEdit&&<><button onClick={()=>setEditing(t)}>Editar</button><button onClick={()=>{if(confirm("Excluir esta tarefa?"))execute(t,"task.delete")}}>Excluir</button></>}</footer></article>
    })}{!rows.length&&<section className="panel"><Empty icon="✓" title="Nenhuma tarefa nesta lista" text={tab==="available"?"As tarefas públicas ainda não assumidas aparecerão aqui.":"Altere os filtros ou aguarde uma nova tarefa."}/></section>}</section></>}
    {(show||editing)&&<TaskModal ctx={ctx} task={editing} close={()=>{setShow(false);setEditing(null)}}/>}</>;
}
function TaskModal({ctx,close,task}:{ctx:Ctx;close:()=>void;task?:Row|null}){
  const manager=taskRole(ctx.boot.user.profile)!=="colaborador";const [visibility,setVisibility]=useState(task?.visibility||"personal");const [query,setQuery]=useState("");const [recipient,setRecipient]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
  const recipients=ctx.boot.profiles.filter(p=>p.email===recipient||`${p.name} ${p.email}`.toLowerCase().includes(query.toLowerCase()));
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setError("");const f=new FormData(e.currentTarget);
    try{await json(await fetch("/api/planner",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:task?"task.update":"task.create",id:task?.id,title:f.get("title"),notes:f.get("notes"),dueDate:f.get("dueDate"),dueTime:f.get("dueTime"),priority:f.get("priority"),estimatedMinutes:f.get("estimatedMinutes"),visibility,assigneeEmail:recipient})}));await ctx.reload();ctx.flash(visibility==="assigned"?"Tarefa enviada. Ela ficará visível somente para o destinatário.":"Tarefa salva.");close()}catch(e:any){setError(e.message)}finally{setBusy(false)}
  }
  return <div className="modal-backdrop"><form className="modal delegation-modal" role="dialog" aria-modal="true" aria-label={task?"Editar tarefa":"Nova tarefa"} onSubmit={submit}><header><h2>{task?"Editar tarefa":"Nova tarefa"}</h2><button type="button" onClick={close} aria-label="Fechar">×</button></header>{manager&&!task&&<label>Quem poderá ver?<select value={visibility} onChange={e=>setVisibility(e.target.value)}><option value="personal">Pessoal — somente eu</option><option value="assigned">Direcionada — somente o destinatário</option><option value="public">Pública — todos os usuários do Planner</option></select></label>}{visibility==="assigned"&&<fieldset><legend>Escolher destinatário</legend><input aria-label="Buscar destinatário" placeholder="Pesquisar nome ou e-mail" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Destinatário" required value={recipient} onChange={e=>setRecipient(e.target.value)}><option value="">Selecione um usuário cadastrado</option>{recipients.map(p=><option value={p.email} key={p.email}>{p.name||p.email} · {p.email}</option>)}</select><small>Após o envio, somente essa pessoa poderá consultar a tarefa.</small></fieldset>}{visibility==="public"&&<p>Todos poderão ver a tarefa. Quem clicar em “Assumir tarefa” ficará identificado como responsável.</p>}<label>O que precisa ser feito?<input name="title" required maxLength={220} defaultValue={task?.title}/></label><label>Orientações<textarea name="notes" defaultValue={task?.notes}/></label><div className="form-row"><label>Prazo final<input name="dueDate" type="date" required={visibility!=="personal"} defaultValue={task?.due_date}/></label><label>Horário limite<input name="dueTime" type="time" defaultValue={task?.due_time}/></label></div><div className="form-row"><label>Urgência<select name="priority" defaultValue={task?.priority||"media"}><option value="baixa">Baixa</option><option value="media">Média</option><option value="alta">Alta</option><option value="urgente">Urgente</option></select></label><label>Tempo estimado (minutos)<input name="estimatedMinutes" type="number" min="0" max="100800" step="1" defaultValue={task?.estimated_minutes||""} placeholder="Ex.: 60"/></label></div>{error&&<p className="planner-inline-error" role="alert">{error}</p>}<footer><button type="button" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?"Salvando...":visibility==="assigned"?"Delegar tarefa":visibility==="public"?"Publicar tarefa":"Salvar tarefa"}</button></footer></form></div>;
}
function PlannerRoles({ctx}:{ctx:Ctx}){
  const [query,setQuery]=useState("");const [busy,setBusy]=useState("");
  async function change(email:string,role:string){if(busy)return;setBusy(email);await act(ctx,{action:"planner.role.update",email,role});setBusy("")}
  return <section className="panel planner-roles"><h2>Perfis do Planner</h2><p>Administradores gerenciam os perfis. Administradores e gerentes delegam tarefas. Colaboradores executam as tarefas recebidas e podem assumir as públicas.</p><label>Buscar usuário<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Nome ou e-mail"/></label>{ctx.boot.profiles.filter(p=>`${p.name} ${p.email}`.toLowerCase().includes(query.toLowerCase())).map(p=><div className="planner-role-row" key={p.email}><span><strong>{p.name||p.email}</strong><small>{p.email}</small></span><select aria-label={"Perfil de "+(p.name||p.email)} disabled={Boolean(busy)||p.email===ctx.boot.user.email||p.role==="Administrador"} value={taskRole(p)} onChange={e=>change(p.email,e.target.value)}><option value="colaborador">Colaborador</option><option value="gerente">Gerente</option><option value="administrador">Administrador</option></select></div>)}</section>;
}

function Calendar({ ctx }: { ctx: Ctx }) {
  const now = new Date(); const [month, setMonth] = useState(new Date(now.getFullYear(), now.getMonth(), 1)); const [show, setShow] = useState(false);const [selectedEvent,setSelectedEvent]=useState<Row|null>(null); const days = calendarDays(month);
  return <><PageTitle eyebrow="AGENDA PERSONALIZADA" title="Calendário" text="Use cores e emojis para reconhecer seus compromissos de relance." action={<button className="primary" onClick={() => setShow(true)}>＋ Novo evento</button>} /><section className="calendar-layout"><article className="panel calendar"><header><button onClick={() => setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}>‹</button><h2>{month.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}</h2><button onClick={() => setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}>›</button></header><div className="weekdays">{["DOM","SEG","TER","QUA","QUI","SEX","SÁB"].map(d=><span key={d}>{d}</span>)}</div><div className="days">{days.map((day,i) => { const key=day?`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`:""; const list=ctx.boot.events.filter(e=>e.event_date===key); return <div className={!day?"blank":key===new Date().toISOString().slice(0,10)?"today":""} key={i}>{day&&<b>{day}</b>}{list.slice(0,3).map(e=><button key={e.id} style={{background:e.color}} title={e.title} onClick={()=>setSelectedEvent(e)}><i>{e.emoji}</i><span>{e.title}</span></button>)}</div>; })}</div></article><aside className="panel event-list"><header><small>PRÓXIMOS</small><h2>Sua agenda</h2></header>{ctx.boot.events.slice(0,10).map(e=><article key={e.id}><span style={{background:e.color}}>{e.emoji}</span><div><strong>{e.title}</strong><small>{humanDate(e.event_date)} {e.event_time&&`às ${e.event_time}`}</small></div><button onClick={()=>act(ctx,{action:"event.delete",id:e.id})}>×</button></article>)}{!ctx.boot.events.length&&<Empty icon="▦" title="Agenda livre" text="Seus eventos aparecerão aqui." />}</aside></section>{selectedEvent&&<div className="modal-backdrop"><section className="modal" role="dialog" aria-modal="true" aria-label="Detalhes do evento"><header><h2>{selectedEvent.emoji} {selectedEvent.title}</h2><button onClick={()=>setSelectedEvent(null)} aria-label="Fechar">×</button></header><p>{humanDate(selectedEvent.event_date)} {selectedEvent.event_time}</p><p>{selectedEvent.notes||"Sem observações"}</p><footer><button onClick={()=>setSelectedEvent(null)}>Fechar</button><button onClick={async()=>{if(await act(ctx,{action:"event.delete",id:selectedEvent.id}))setSelectedEvent(null)}}>Excluir evento</button></footer></section></div>}{show&&<EventModal ctx={ctx} close={()=>setShow(false)} />}</>;
}

function EventModal({ ctx, close }: { ctx: Ctx; close: () => void }) { async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await act(ctx,{action:"event.create",title:f.get("title"),eventDate:f.get("date"),eventTime:f.get("time"),emoji:f.get("emoji"),color:f.get("color"),notes:f.get("notes")});close();} return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><header><div><small>CALENDÁRIO</small><h2>Novo evento</h2></div><button type="button" onClick={close}>×</button></header><label>Título<input name="title" required placeholder="Nome do compromisso" /></label><div className="form-row"><label>Data<input name="date" type="date" required /></label><label>Horário<input name="time" type="time" /></label></div><div className="form-row"><label>Emoji<select name="emoji"><option>📌</option><option>📅</option><option>🎯</option><option>🤝</option><option>🎉</option><option>💼</option><option>⚠️</option></select></label><label>Cor<input name="color" type="color" defaultValue="#4f7cff" /></label></div><label>Observações<textarea name="notes" /></label><footer><button type="button" onClick={close}>Cancelar</button><button className="primary">Criar evento</button></footer></form></div>; }

function Documents({ ctx }: { ctx: Ctx }) {
  const input = useRef<HTMLInputElement>(null); const [busy,setBusy]=useState(false); const [query,setQuery]=useState("");
  async function upload(file?: File){if(!file)return;setBusy(true);const form=new FormData();form.set("action","document.upload");form.set("file",file);try{await json(await fetch("/api/planner",{method:"POST",body:form}));await ctx.reload();ctx.flash("Documento salvo.");}catch(e:any){ctx.flash(e.message);}finally{setBusy(false);}}
  const docs=ctx.boot.documents.filter(d=>d.file_name.toLowerCase().includes(query.toLowerCase()));
  return <><PageTitle eyebrow="ARQUIVOS" title="Documentos" text="Salve, visualize, renomeie e organize arquivos importantes." action={<><input ref={input} type="file" hidden onChange={e=>upload(e.target.files?.[0])}/><button className="primary" disabled={busy} onClick={()=>input.current?.click()}>{busy?"Enviando...":"↑ Enviar documento"}</button></>} /><div className="document-toolbar"><label>⌕<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Pesquisar documento..." /></label><span>{docs.length} arquivo(s)</span></div><section className="document-grid">{docs.map(doc=><article className="document-card" key={doc.id}><span className={`file-kind ${fileKind(doc.file_name)}`}>{fileKind(doc.file_name).toUpperCase()}</span><div><strong>{doc.file_name}</strong><small>{formatBytes(doc.size)} • {humanDate(doc.updated_at?.slice(0,10))}</small></div><footer><a href={`/api/planner?action=document&id=${doc.id}`} target="_blank">Abrir</a><button onClick={()=>{const name=prompt("Novo nome do documento:",doc.file_name);if(name)act(ctx,{action:"document.rename",id:doc.id,fileName:name});}}>Renomear</button><button className="delete" onClick={()=>act(ctx,{action:"document.delete",id:doc.id})}>Excluir</button></footer></article>)}{!docs.length&&<div className="panel full-empty"><Empty icon="▤" title="Nenhum documento" text="Envie arquivos de até 25 MB para começar." /></div>}</section></>;
}

function EmailHub(){return <><PageTitle eyebrow="COMUNICAÇÃO" title="E-mail" text="Acesse sua caixa de entrada corporativa com segurança." /><section className="email-layout"><article className="panel email-connect"><span className="email-icon">✉</span><small>CAIXA DE ENTRADA</small><h2>Conecte seu provedor</h2><p>Por segurança, a senha do seu e-mail nunca é armazenada no GWL NEXO. Escolha o serviço e faça a autenticação diretamente no provedor.</p><a href="https://mail.google.com/" target="_blank" rel="noreferrer" className="gmail"><b>G</b><span><strong>Abrir Gmail</strong><small>Conta Google ou Google Workspace</small></span><i>↗</i></a><a href="https://outlook.office.com/mail/" target="_blank" rel="noreferrer" className="outlook"><b>O</b><span><strong>Abrir Outlook</strong><small>Microsoft 365 ou Outlook.com</small></span><i>↗</i></a></article><article className="panel email-preview"><header><span>✉</span><div><strong>Central de e-mails</strong><small>Integração protegida</small></div></header><div className="fake-inbox"><i /><i /><i /><i /></div><h3>Seus e-mails permanecem no provedor</h3><p>O Planner abre sua caixa oficial em uma nova aba, preservando filtros, anexos e todas as proteções do Gmail ou Outlook.</p><a href="mailto:">＋ Escrever novo e-mail</a></article></section></>}

type BoardCard={id:string;title:string;notes:string;status:"todo"|"doing"|"done";priority:"baixa"|"media"|"alta";dueDate:string;assignee:string};
function readBoardPayload(value:unknown){try{const parsed=JSON.parse(String(value||"[]"));if(Array.isArray(parsed))return{strokes:parsed,cards:[] as BoardCard[]};return{strokes:Array.isArray(parsed.strokes)?parsed.strokes:[],cards:Array.isArray(parsed.cards)?parsed.cards:[]};}catch{return{strokes:[],cards:[] as BoardCard[]}}}

function Whiteboard({ctx}:{ctx:Ctx}){const boards=ctx.boot.boards||[];const [activeId,setActiveId]=useState(boards[0]?.id||"");const active=boards.find(board=>board.id===activeId)||boards[0]||null;const canvas=useRef<HTMLCanvasElement>(null);const strokes=useRef<any[]>([]);const current=useRef<any[]>([]);const [color,setColor]=useState("#476dff");const [width,setWidth]=useState(4);const [members,setMembers]=useState<string[]>([]);const [cards,setCards]=useState<BoardCard[]>([]);const [tab,setTab]=useState<"tasks"|"draw">("tasks");const [showTask,setShowTask]=useState(false);const [dragged,setDragged]=useState("");const drawing=useRef(false);const owner=active?.owner_email===ctx.boot.user.email;
  function paint(){const c=canvas.current;if(!c)return;const x=c.getContext("2d")!;x.clearRect(0,0,c.width,c.height);x.fillStyle="#ffffff";x.fillRect(0,0,c.width,c.height);x.lineCap="round";x.lineJoin="round";for(const s of strokes.current){x.strokeStyle=s.color;x.lineWidth=s.width;x.beginPath();s.points.forEach((p:any,i:number)=>i?x.lineTo(p.x,p.y):x.moveTo(p.x,p.y));x.stroke();}}
  useEffect(()=>{if(!active){strokes.current=[];setCards([]);setMembers([]);return}const data=readBoardPayload(active.payload);strokes.current=data.strokes;setCards(data.cards);try{setMembers(JSON.parse(active.allowed_emails||"[]"))}catch{setMembers([])}requestAnimationFrame(paint)},[active]);
  useEffect(()=>{if(tab==="draw")requestAnimationFrame(paint)},[tab,activeId]);
  function point(e:ReactPointerEvent<HTMLCanvasElement>){const r=e.currentTarget.getBoundingClientRect();return{x:(e.clientX-r.left)*(e.currentTarget.width/r.width),y:(e.clientY-r.top)*(e.currentTarget.height/r.height)}}
  function down(e:ReactPointerEvent<HTMLCanvasElement>){drawing.current=true;current.current=[point(e)];e.currentTarget.setPointerCapture(e.pointerId)} function move(e:ReactPointerEvent<HTMLCanvasElement>){if(!drawing.current)return;current.current.push(point(e));const temp={color,width,points:current.current};strokes.current.push(temp);paint();strokes.current.pop()} function up(){if(!drawing.current)return;drawing.current=false;strokes.current.push({color,width,points:[...current.current]});current.current=[];paint()}
  function moveCard(id:string,status:BoardCard["status"]){setCards(items=>items.map(card=>card.id===id?{...card,status}:card))}
  function addCard(card:Omit<BoardCard,"id">){setCards(items=>[{...card,id:crypto.randomUUID()},...items]);setShowTask(false)}
  async function save(){if(!active)return;await act(ctx,{action:"board.save",boardId:active.id,title:active.title,allowedEmails:members,payload:JSON.stringify({version:2,strokes:strokes.current,cards})});}
  async function createBoard(){const title=prompt("Nome da nova lousa:","Minha lousa");if(!title?.trim())return;try{const result=await json(await fetch("/api/planner",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"board.save",title:title.trim(),allowedEmails:[],payload:JSON.stringify({version:2,strokes:[],cards:[]})})}));setActiveId(result.id);await ctx.reload();ctx.flash("Lousa criada.")}catch(e:any){ctx.flash(e.message)}}
  async function deleteBoard(){if(!active||!owner||!confirm(`Excluir a lousa “${active.title}”?`))return;await act(ctx,{action:"board.delete",boardId:active.id});setActiveId(boards.find(board=>board.id!==active.id)?.id||"")}
  const columns:Array<{id:BoardCard["status"];label:string;hint:string}>=[{id:"todo",label:"A fazer",hint:"Tarefas planejadas"},{id:"doing",label:"Em andamento",hint:"Trabalho em execução"},{id:"done",label:"Concluído",hint:"Entregas finalizadas"}];
  return <><PageTitle eyebrow="COLABORAÇÃO VISUAL" title="Lousas compartilhadas" text="Crie ambientes de tarefas e compartilhe cada lousa somente com os usuários escolhidos." action={<div className="board-actions"><button onClick={createBoard}>＋ Nova lousa</button>{active&&<button onClick={()=>setShowTask(true)}>＋ Nova tarefa</button>}<button className="primary" disabled={!active} onClick={save}>Salvar alterações</button></div>} />
    <section className="board-workspace"><aside className="panel board-list"><header><div><small>SEUS AMBIENTES</small><h2>Lousas disponíveis</h2></div><button onClick={createBoard}>＋</button></header><div><small>MINHAS LOUSAS</small>{boards.filter(board=>board.owner_email===ctx.boot.user.email).map(board=><button className={active?.id===board.id?"active":""} onClick={()=>setActiveId(board.id)} key={board.id}><span>◇</span><div><strong>{board.title}</strong><small>{readBoardPayload(board.payload).cards.length} tarefa(s)</small></div></button>)}<small>COMPARTILHADAS COMIGO</small>{boards.filter(board=>board.owner_email!==ctx.boot.user.email).map(board=><button className={active?.id===board.id?"active":""} onClick={()=>setActiveId(board.id)} key={board.id}><span>↗</span><div><strong>{board.title}</strong><small>Compartilhada por {board.owner_email}</small></div></button>)}</div></aside><main>{active?<><div className="board-active-head"><div><span>{owner?"MINHA LOUSA":"LOUSA COMPARTILHADA"}</span><h2>{active.title}</h2><p>{owner?`${members.length} usuário(s) com permissão`:`Criada por ${active.owner_email}`}</p></div>{owner&&<button className="delete" onClick={deleteBoard}>Excluir lousa</button>}</div><div className="board-tabs"><button className={tab==="tasks"?"active":""} onClick={()=>setTab("tasks")}>✓ Quadro de tarefas</button><button className={tab==="draw"?"active":""} onClick={()=>setTab("draw")}>✎ Desenho livre</button>{owner&&<details><summary>Compartilhar com usuários</summary><div>{ctx.boot.profiles.filter(p=>p.email!==ctx.boot.user.email).slice(0,100).map(p=><label key={p.email}><input type="checkbox" checked={members.includes(p.email)} onChange={()=>setMembers(v=>v.includes(p.email)?v.filter(x=>x!==p.email):[...v,p.email])}/>{p.name||p.email}</label>)}</div></details>}</div>{tab==="tasks"?<section className="kanban-board">{columns.map(column=><article className={`kanban-column ${column.id}`} key={column.id} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(dragged)moveCard(dragged,column.id);setDragged("")}}><header><div><h2>{column.label}</h2><small>{column.hint}</small></div><b>{cards.filter(card=>card.status===column.id).length}</b></header><div>{cards.filter(card=>card.status===column.id).map(card=><section className="kanban-card" draggable onDragStart={()=>setDragged(card.id)} key={card.id}><div className="card-flags"><span className={`priority-label ${card.priority}`}>{card.priority}</span>{card.dueDate&&<time>{humanDate(card.dueDate)}</time>}</div><h3>{card.title}</h3>{card.notes&&<p>{card.notes}</p>}<label>Responsável<select value={card.assignee} onChange={e=>setCards(items=>items.map(item=>item.id===card.id?{...item,assignee:e.target.value}:item))}><option value="">Não atribuído</option>{ctx.boot.profiles.slice(0,100).map(p=><option value={p.email} key={p.email}>{p.name||p.email}</option>)}</select></label><footer><select aria-label="Mover tarefa" value={card.status} onChange={e=>moveCard(card.id,e.target.value as BoardCard["status"])}><option value="todo">A fazer</option><option value="doing">Em andamento</option><option value="done">Concluído</option></select><button onClick={()=>setCards(items=>items.filter(item=>item.id!==card.id))} aria-label="Excluir tarefa">×</button></footer></section>)}{!cards.some(card=>card.status===column.id)&&<div className="kanban-empty">Arraste uma tarefa para cá</div>}</div></article>)}</section>:<section className="board-shell panel"><header><div className="board-tools"><label>Cor<input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label><button onClick={()=>setColor("#ffffff")}>⌫ Borracha</button><label>Traço<input type="range" min="2" max="18" value={width} onChange={e=>setWidth(Number(e.target.value))}/></label><button onClick={()=>{strokes.current.pop();paint()}}>↶ Desfazer</button><button onClick={()=>{strokes.current=[];paint()}}>Limpar desenho</button></div></header><div className="canvas-wrap"><canvas ref={canvas} width="1200" height="650" onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up}/></div></section>}</>:<section className="panel board-welcome"><Empty icon="◇" title="Crie sua primeira lousa" text="Depois, adicione tarefas e escolha quem pode acompanhar e colaborar."/><button className="primary" onClick={createBoard}>＋ Criar lousa</button></section>}</main></section>
    {showTask&&<BoardTaskModal profiles={ctx.boot.profiles} close={()=>setShowTask(false)} create={addCard}/>}</>}

function BoardTaskModal({profiles,close,create}:{profiles:Row[];close:()=>void;create:(card:Omit<BoardCard,"id">)=>void}){function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);create({title:String(f.get("title")||"").trim(),notes:String(f.get("notes")||"").trim(),status:"todo",priority:String(f.get("priority")||"media") as BoardCard["priority"],dueDate:String(f.get("dueDate")||""),assignee:String(f.get("assignee")||"")})}return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><header><div><small>LOUSA DA EQUIPE</small><h2>Nova tarefa interativa</h2></div><button type="button" onClick={close}>×</button></header><label>Título<input name="title" required minLength={3} placeholder="Ex.: Revisar documentos do contrato"/></label><label>Detalhes<textarea name="notes" placeholder="Contexto, checklist ou observações..."/></label><div className="form-row"><label>Prazo<input name="dueDate" type="date"/></label><label>Prioridade<select name="priority" defaultValue="media"><option value="baixa">Baixa</option><option value="media">Média</option><option value="alta">Alta</option></select></label></div><label>Responsável<select name="assignee"><option value="">Não atribuído</option>{profiles.slice(0,100).map(p=><option value={p.email} key={p.email}>{p.name||p.email}</option>)}</select></label><footer><button type="button" onClick={close}>Cancelar</button><button className="primary">Adicionar à lousa</button></footer></form></div>}

function Market({ctx}:{ctx:Ctx}){
  const [storeFilter,setStoreFilter]=useState("");const [comparison,setComparison]=useState<Row[]>([]);const [savedOnly,setSavedOnly]=useState(false);const [saving,setSaving]=useState("");
  const [query,setQuery]=useState("eletrônicos");const [activeQuery,setActiveQuery]=useState("");const [data,setData]=useState<Row|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [sort,setSort]=useState("recommended");const [minPrice,setMinPrice]=useState("");const [maxPrice,setMaxPrice]=useState("");const [gender,setGender]=useState("");const [size,setSize]=useState("");const requestNumber=useRef(0);
  const niches=["Camisa old money","Camiseta oversized","Vestido","Calça alfaiataria","Moda feminina","Moda masculina","Fone bluetooth","Notebook","Geladeira","Aspirador","Ferramentas"];
  async function run(term:string,page=0){const clean=term.trim();if(!clean)return;const requestId=++requestNumber.current;setQuery(clean);setActiveQuery(clean);setBusy(true);setError("");
    if(!page){setData(null);setSort("recommended");setMinPrice("");setMaxPrice("");setGender("");setSize("");setStoreFilter("");}
    try{const result=await json(await fetch(`/api/planner?action=products&q=${encodeURIComponent(clean)}&page=${page}`));if(requestId!==requestNumber.current)return;
      setData(old=>{if(!page||!old)return result;const results=[...new Map([...old.results,...result.results].map(p=>[p.link,p])).values()];return {...result,results,inspectedCount:Number(old.inspectedCount||0)+Number(result.inspectedCount||0),hasMore:result.hasMore&&results.length>old.results.length}});
      localStorage.setItem("gwl-market-last-query",clean);
    }catch(e:any){if(requestId===requestNumber.current)setError(e.message)}finally{if(requestId===requestNumber.current)setBusy(false)}
  }
  async function saveOffer(p:Row){if(saving)return;setSaving(p.link);const existing=ctx.boot.links.find(l=>l.url===p.link&&l.kind==="product");await act(ctx,existing?{action:"link.delete",id:existing.id}:{action:"link.create",title:p.title,url:p.link,kind:"product",color:"#8b5cf6"});setSaving("");}
  useEffect(()=>{run(localStorage.getItem("gwl-market-last-query")||"fone bluetooth")},[]);
  async function search(e:FormEvent){e.preventDefault();await run(query)}
  const products=useMemo(()=>{let items=[...(data?.results||[])].filter(item=>(!minPrice||Number(item.price)>=Number(minPrice))&&(!maxPrice||Number(item.price)<=Number(maxPrice))&&(!gender||String(item.gender||"").toLowerCase().includes(gender))&&(!size||(item.sizes||[]).includes(size))&&(!storeFilter||item.store===storeFilter));if(sort==="price")return items.sort((a,b)=>Number(a.price)-Number(b.price));if(sort==="rating")return items.sort((a,b)=>Number(b.rating||0)-Number(a.rating||0)||Number(b.reviewCount||0)-Number(a.reviewCount||0)||Number(b.score||0)-Number(a.score||0));if(sort==="discount")return items.sort((a,b)=>Number(b.savingsPercent||0)-Number(a.savingsPercent||0)||Number(b.score||0)-Number(a.score||0));return items.sort((a,b)=>Number(b.score||0)-Number(a.score||0))},[data,sort,minPrice,maxPrice,gender,size,storeFilter]);
  const money=(value:number,currency="BRL")=>new Intl.NumberFormat("pt-BR",{style:"currency",currency}).format(value);
  return <><PageTitle eyebrow="GWL OFERTAS" title="Encontre o produto certo, pelo melhor valor" text="Compare anúncios, salve favoritos e escolha por preço, características e avaliações disponíveis."/>
    <div className="offer-utility-bar"><button aria-pressed={savedOnly} onClick={()=>setSavedOnly(v=>!v)}>♡ Favoritos ({ctx.boot.links.filter(l=>l.kind==="product").length})</button><span>Selecione até 4 anúncios para comparar</span></div>
    {savedOnly&&<section className="panel saved-offers"><h2>Meus produtos favoritos</h2>{ctx.boot.links.filter(l=>l.kind==="product").map(l=><div key={l.id}><a href={l.url} target="_blank" rel="noreferrer">{l.title} ↗</a><button onClick={()=>act(ctx,{action:"link.delete",id:l.id})} aria-label="Remover favorito">×</button></div>)}{!ctx.boot.links.some(l=>l.kind==="product")&&<p>Use “Salvar” em um anúncio para encontrá-lo aqui depois.</p>}</section>}
    {comparison.length>0&&<section className="panel offer-comparison"><header><h2>Comparar anúncios</h2><button onClick={()=>setComparison([])}>Limpar</button></header><div className="comparison-scroll"><table><thead><tr><th>Detalhe</th>{comparison.map(p=><th key={p.link}><img src={p.image} alt=""/><span>{p.title}</span><button onClick={()=>setComparison(old=>old.filter(i=>i.link!==p.link))}>Remover</button></th>)}</tr></thead><tbody>{[["Loja",(p:Row)=>p.store],["Preço",(p:Row)=>money(p.price)],["Avaliações",(p:Row)=>p.rating?`${p.rating}/5 · ${p.reviewCount||0} avaliações`:"Não informadas"],["Composição",(p:Row)=>p.composition||"Não informada"],["Tamanhos",(p:Row)=>(p.sizes||[]).join(", ")||"Consultar loja"]].map(([label,get]:any)=><tr key={label}><th>{label}</th>{comparison.map(p=><td key={p.link}>{get(p)}</td>)}</tr>)}<tr><th>Anúncio</th>{comparison.map(p=><td key={p.link}><a href={p.link} target="_blank" rel="noreferrer">Abrir na loja ↗</a></td>)}</tr></tbody></table></div><p>Preços da consulta, sujeitos a estoque e tamanho. Compare frete e condições na loja.</p></section>}<form className="market-search" onSubmit={search}><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="O que você quer comprar? Ex.: camisa old money, vestido, fone bluetooth..."/><button disabled={busy}>{busy?"Buscando em várias lojas...":"Pesquisar ofertas"}</button></form><div className="market-niches">{niches.map(niche=><button className={activeQuery.toLowerCase()===niche.toLowerCase()?"active":""} onClick={()=>run(niche)} key={niche}>{niche}</button>)}</div>{error&&<div className="planner-inline-error">{error}</div>}{busy&&<><div className="market-deep-status"><span/><div><strong>Pesquisa profunda em andamento</strong><small>Consultando catálogos, comparadores e lojas para calcular o melhor custo-benefício.</small></div></div>{!data&&<section className="product-grid market-loading">{[1,2,3,4,5,6,7,8].map(i=><article key={i}><div/><i/><i/><b/></article>)}</section>}</>}{data&&<><div className="market-result-head"><div><small>SELEÇÃO GWL</small><h2>Melhores ofertas para “{activeQuery}”</h2><p><b>{products.length}</b> ofertas completas • {Number(data.inspectedCount||products.length)} anúncios analisados • atualização {new Date(data.updatedAt).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}</p></div><label>Ordenar por<select value={sort} onChange={e=>setSort(e.target.value)}><option value="recommended">{data.mode==="fashion"?"Estilo e composição":"Melhor custo-benefício"}</option><option value="price">Menor preço</option><option value="rating">Melhor avaliação</option><option value="discount">Maior desconto</option></select></label></div><div className="market-toolbar"><label className="store-filter">Loja<select value={storeFilter} onChange={e=>setStoreFilter(e.target.value)}><option value="">Todas as lojas</option>{[...new Set<string>((data.results||[]).map((p:Row)=>p.store))].map(name=><option key={name}>{name}</option>)}</select></label><div className="market-sort-chips"><button className={sort==="recommended"?"active":""} onClick={()=>setSort("recommended")}>✦ {data.mode==="fashion"?"Estilo e composição":"Seleção GWL"}</button><button className={sort==="price"?"active":""} onClick={()=>setSort("price")}>↓ Menor preço</button><button className={sort==="rating"?"active":""} onClick={()=>setSort("rating")}>★ Melhor avaliados</button><button className={sort==="discount"?"active":""} onClick={()=>setSort("discount")}>% Maior desconto</button></div><div className="market-price-filter"><span>Faixa de preço</span><input type="number" min="0" inputMode="numeric" value={minPrice} onChange={e=>setMinPrice(e.target.value)} placeholder="Mínimo"/><i>—</i><input type="number" min="0" inputMode="numeric" value={maxPrice} onChange={e=>setMaxPrice(e.target.value)} placeholder="Máximo"/></div></div>{data.mode==="fashion"&&<section className="fashion-tools"><div><strong>{data.style?data.style+" · seleção por características":"Moda · escolha por estilo"}</strong><p>Peças selecionadas pelo tipo, descrição e composição informados pela loja. A combinação de estilo é uma sugestão; confira fotos, medidas e acabamento.</p></div><label>Público<select value={gender} onChange={e=>setGender(e.target.value)}><option value="">Todos</option><option value="masculino">Masculino</option><option value="feminino">Feminino</option></select></label><label>Tamanho em estoque<select value={size} onChange={e=>setSize(e.target.value)}><option value="">Todos</option>{[...new Set<string>((data.results||[]).flatMap((p:Row)=>p.sizes||[]))].map(t=><option key={t}>{t}</option>)}</select></label></section>}<div className="market-retailers"><small>LOJAS ENCONTRADAS</small><div>{(data.retailers||[]).map((retailer:Row)=><span key={retailer.name}>{retailer.name}<b>{retailer.found}</b></span>)}</div></div><div className="market-source-status">{(data.sources||[]).map((source:Row)=><span className={source.found?"ok":"off"} key={source.name}><i/>{source.name}<b>{source.found?`${source.found} anúncios`:source.status}</b></span>)}</div><div className="ranking-criteria">{(data.criteria||[]).map((criterion:string)=><span key={criterion}>✓ {criterion}</span>)}</div>{products.length?<section className={"product-grid smart-products"+(data.mode==="fashion"?" fashion-products":"")}>{products.map((p:Row,index:number)=><article key={`${p.store}-${p.id}`}><div className="product-badges"><b className={index===0&&sort==="recommended"?"best":""}>{sort==="recommended"?p.badge:index===0?sort==="price"?"Mais barato":sort==="rating"?(p.rating?"Mais bem avaliado":"Sem avaliações"):"Maior desconto":p.badge}</b><span title="Pontuação de correspondência calculada com os dados disponíveis">{p.score}/100</span></div><div className="product-image"><img src={String(p.image).replace("http://","https://")} alt={p.title} loading="lazy" referrerPolicy="no-referrer" onError={e=>{e.currentTarget.style.display="none";e.currentTarget.parentElement?.classList.add("image-error")}}/></div><div className="offer-actions"><button disabled={Boolean(saving)} onClick={()=>saveOffer(p)}>{ctx.boot.links.some(l=>l.kind==="product"&&l.url===p.link)?"♥ Salvo":"♡ Salvar"}</button><button aria-pressed={comparison.some(i=>i.link===p.link)} onClick={()=>setComparison(old=>old.some(i=>i.link===p.link)?old.filter(i=>i.link!==p.link):old.length<4?[...old,p]:old)}>{comparison.some(i=>i.link===p.link)?"✓ Comparando":"Comparar"}</button></div><div className="product-origin"><small>{p.store} • {p.condition}</small>{p.comparisonSource?<b>Comparado no {p.comparisonSource}</b>:p.freeShipping&&<b>Frete grátis</b>}</div><h3>{p.title}</h3><div className="product-reputation"><span className={p.rating?"rated":""}>★ {p.rating?Number(p.rating).toFixed(1):"Sem avaliações"}</span><small>{p.reviewCount?`${p.reviewCount} avaliações`:p.sellerStatus?String(p.sellerStatus):"Avaliações não informadas"}</small></div>{data.mode==="fashion"&&<div className="fashion-facts"><p>{p.composition||"Composição não informada"}</p><small>{(p.reasons||[]).join(" · ")}</small><p>Tamanhos: {(p.sizes||[]).join(" · ")}</p></div>}<div className="product-price">{Number(p.originalPrice)>Number(p.price)&&<><del>{money(Number(p.originalPrice),p.currency||"BRL")}</del>{p.savingsPercent>0&&<em>-{p.savingsPercent}%</em>}</>}<strong>{data.mode==="fashion"&&<small>A partir de </small>}{money(Number(p.price),p.currency||"BRL")}</strong><small>{p.comparisonSource?"Melhor preço encontrado entre as lojas":data.mode==="fashion"?"Preço no tamanho "+p.priceSize+". Frete calculado pela loja.":"Preço informado pela loja"}</small></div><a href={p.link} target="_blank" rel="noreferrer">{p.comparisonSource?`Comparar em ${p.availableStores?.length||p.storeCount||"várias"} lojas ↗`:"Abrir anúncio e comprar ↗"}</a></article>)}</section>:<section className="panel market-empty"><Empty icon="⌕" title={data.results?.length?"Nenhuma oferta com estes filtros":"Nenhuma oferta completa encontrada"} text={data.results?.length?"Ajuste preço, público ou tamanho para ver outras opções.":data.mode==="fashion"?"Não encontramos peças em estoque que correspondam ao estilo e aos atributos pedidos. Experimente outro tecido, peça ou estilo.":"As lojas consultadas não entregaram anúncios completos agora. Tente novamente ou detalhe marca e modelo."}/></section>}{data.hasMore&&<button className="load-more-offers primary" disabled={busy} onClick={()=>run(activeQuery,Number(data.page||0)+1)}>{busy?"Buscando mais...":"Carregar mais ofertas"}</button>}</>}</>}

function Links({ctx}:{ctx:Ctx}){const [show,setShow]=useState(false);return <><PageTitle eyebrow="ATALHOS" title="Sites e aplicativos" text="Cadastre os sistemas mais usados e abra tudo com um clique." action={<button className="primary" onClick={()=>setShow(true)}>＋ Adicionar atalho</button>}/><section className="links-grid">{ctx.boot.links.map(link=><article key={link.id} style={{"--link-color":link.color} as any}><span>{link.kind==="app"?"▣":"↗"}</span><div><small>{link.kind==="app"?"APLICATIVO":"SITE"}</small><h3>{link.title}</h3><p>{new URL(link.url).hostname}</p></div><footer><a href={link.url} target="_blank" rel="noreferrer">Abrir {link.kind==="app"?"aplicativo":"site"} →</a><button onClick={()=>act(ctx,{action:"link.delete",id:link.id})}>×</button></footer></article>)}{!ctx.boot.links.length&&<div className="panel full-empty"><Empty icon="↗" title="Nenhum atalho cadastrado" text="Adicione seus sites e aplicativos de trabalho."/></div>}</section>{show&&<LinkModal ctx={ctx} close={()=>setShow(false)}/>}</>}

function LinkModal({ctx,close}:{ctx:Ctx;close:()=>void}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);await act(ctx,{action:"link.create",title:f.get("title"),url:f.get("url"),kind:f.get("kind"),color:f.get("color")});close()}return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><header><div><small>NOVO ATALHO</small><h2>Adicionar site ou aplicativo</h2></div><button type="button" onClick={close}>×</button></header><label>Nome<input name="title" required placeholder="Ex.: Tirvu, Hostinger, Gmail..."/></label><label>Link<input name="url" type="url" required placeholder="https://..."/></label><div className="form-row"><label>Tipo<select name="kind"><option value="site">Site</option><option value="app">Aplicativo</option></select></label><label>Cor<input name="color" type="color" defaultValue="#4f7cff"/></label></div><footer><button type="button" onClick={close}>Cancelar</button><button className="primary">Salvar atalho</button></footer></form></div>}

function Settings({user,flash}:{user:Boot["user"];flash:(m:string)=>void}){
  const themes=[{id:"nexo-dark",name:"Nexo Dark",description:"Escuro profissional",colors:["#060b16","#3f72ff","#101827"]},{id:"midnight",name:"Midnight",description:"Azul e violeta",colors:["#080d1d","#8b5cf6","#171e33"]},{id:"aurora",name:"Aurora",description:"Escuro com ciano",colors:["#06171b","#19c7b3","#10272b"]},{id:"carbon",name:"Carbon",description:"Preto e grafite",colors:["#090a0c","#d7e0ec","#181a1f"]},{id:"ocean",name:"Azul Nexo",description:"Claro corporativo",colors:["#071833","#356fff","#eef4ff"]},{id:"graphite",name:"Grafite",description:"Neutro e laranja",colors:["#15191f","#f2943f","#f3f5f7"]},{id:"light",name:"Claro",description:"Limpo e luminoso",colors:["#ffffff","#246bfe","#f1f5fb"]},{id:"contrast",name:"Alto contraste",description:"Acessibilidade",colors:["#000000","#ffd400","#101010"]}];
  const accents=[{id:"blue",name:"Azul",color:"#4778ff"},{id:"cyan",name:"Ciano",color:"#18bcd1"},{id:"violet",name:"Violeta",color:"#895cf5"},{id:"orange",name:"Laranja",color:"#f28a35"},{id:"green",name:"Verde",color:"#16a67a"},{id:"rose",name:"Rosa",color:"#e85e9c"}];
  const [selected,setSelected]=useState({theme:"nexo-dark",accent:"blue",density:"comfortable",shape:"soft"});
  useEffect(()=>{setSelected({theme:localStorage.getItem("gwl-planner-theme")||"nexo-dark",accent:localStorage.getItem("gwl-planner-accent")||"blue",density:localStorage.getItem("gwl-planner-density")||"comfortable",shape:localStorage.getItem("gwl-planner-shape")||"soft"})},[]);
  function choose(key:"theme"|"accent"|"density"|"shape",value:string){localStorage.setItem(`gwl-planner-${key}`,value);setSelected(current=>({...current,[key]:value}));applyPlannerPreferences();flash("Personalização aplicada.")}
  return <><PageTitle eyebrow="PREFERÊNCIAS" title="Personalização" text="Monte o Planner do seu jeito. As escolhas ficam salvas neste dispositivo."/><section className="settings-grid advanced-settings"><article className="panel account-panel"><header><small>PERFIL</small><h2>Sua conta</h2></header><div className="account-card"><span>{initials(user.name)}</span><div><strong>{user.name}</strong><small>{user.email}</small><i>{user.profile.role}</i></div></div><p>O Planner utiliza seu acesso corporativo do GWL NEXO.</p><div className="preference-summary"><span>Tema<b>{themes.find(t=>t.id===selected.theme)?.name}</b></span><span>Densidade<b>{selected.density==="compact"?"Compacta":"Confortável"}</b></span><span>Cartões<b>{selected.shape==="square"?"Retos":"Arredondados"}</b></span></div></article><article className="panel theme-panel"><header><small>APARÊNCIA</small><h2>Temas do Planner</h2></header><div>{themes.map(t=><button className={selected.theme===t.id?"selected":""} key={t.id} onClick={()=>choose("theme",t.id)}><span>{t.colors.map(c=><i key={c} style={{background:c}}/>)}</span><strong>{t.name}</strong><small>{t.description}</small></button>)}</div></article><article className="panel preference-panel"><header><small>COR DE DESTAQUE</small><h2>Escolha seu tom</h2></header><div className="accent-options">{accents.map(accent=><button className={selected.accent===accent.id?"selected":""} key={accent.id} onClick={()=>choose("accent",accent.id)}><i style={{background:accent.color}}/><span>{accent.name}</span></button>)}</div></article><article className="panel preference-panel"><header><small>LAYOUT</small><h2>Densidade e formato</h2></header><div className="layout-options"><button className={selected.density==="comfortable"?"selected":""} onClick={()=>choose("density","comfortable")}><b>☰</b><span><strong>Confortável</strong><small>Mais respiro entre elementos</small></span></button><button className={selected.density==="compact"?"selected":""} onClick={()=>choose("density","compact")}><b>≡</b><span><strong>Compacto</strong><small>Mais informação na tela</small></span></button><button className={selected.shape==="soft"?"selected":""} onClick={()=>choose("shape","soft")}><b>▢</b><span><strong>Arredondado</strong><small>Cartões com curvas suaves</small></span></button><button className={selected.shape==="square"?"selected":""} onClick={()=>choose("shape","square")}><b>□</b><span><strong>Reto</strong><small>Visual técnico e preciso</small></span></button></div></article></section></>}

function PageTitle({eyebrow,title,text,action}:{eyebrow:string;title:string;text:string;action?:React.ReactNode}){return <section className="planner-heading"><div><small>{eyebrow}</small><h1>{title}</h1><p>{text}</p></div>{action&&<aside>{action}</aside>}</section>}
function Empty({icon,title,text}:{icon:string;title:string;text:string}){return <div className="empty"><span>{icon}</span><strong>{title}</strong><p>{text}</p></div>}
function initials(value:string){return value.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()||"GW"}
function firstName(value:string){return value.trim().split(/\s+/)[0]||"bem-vindo"}
function humanDate(value:string){if(!value)return"";const date=new Date(`${value}T12:00:00`);return Number.isNaN(date.getTime())?value:date.toLocaleDateString("pt-BR",{day:"2-digit",month:"short",year:"numeric"})}
function dateTime(value:string){if(!value)return"";const date=new Date(value.endsWith("Z")||value.includes("T")?value:`${value.replace(" ","T")}Z`);return Number.isNaN(date.getTime())?value:date.toLocaleString("pt-BR",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}
function shortTime(value:string){if(!value)return"";const date=new Date(value.endsWith("Z")||value.includes("T")?value:`${value.replace(" ","T")}Z`);return Number.isNaN(date.getTime())?"":date.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}
function relativeTime(value:string){const time=new Date(value).getTime();if(!Number.isFinite(time))return"recente";const minutes=Math.max(1,Math.round((Date.now()-time)/60000));if(minutes<60)return`há ${minutes} min`;const hours=Math.round(minutes/60);if(hours<24)return`há ${hours} h`;const days=Math.round(hours/24);return`há ${days} dia${days===1?"":"s"}`}
function applyPlannerPreferences(){const root=document.documentElement;root.dataset.plannerTheme=localStorage.getItem("gwl-planner-theme")||"nexo-dark";root.dataset.plannerAccent=localStorage.getItem("gwl-planner-accent")||"blue";root.dataset.plannerDensity=localStorage.getItem("gwl-planner-density")||"comfortable";root.dataset.plannerShape=localStorage.getItem("gwl-planner-shape")||"soft"}
function calendarDays(month:Date){const count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return [...Array(month.getDay()).fill(null),...Array.from({length:count},(_,i)=>i+1)]}
function fileKind(name:string){const ext=name.split(".").pop()?.toLowerCase()||"file";return ["pdf","doc","docx","xls","xlsx","png","jpg","jpeg","zip"].includes(ext)?ext.replace("docx","doc").replace("xlsx","xls").replace("jpeg","jpg"):"file"}
function formatBytes(value:number){if(value<1024)return`${value} B`;if(value<1024*1024)return`${(value/1024).toFixed(1)} KB`;return`${(value/1024/1024).toFixed(1)} MB`}

function GlobalSearch({ctx,query,setQuery,open,close}:{ctx:Ctx;query:string;setQuery:(v:string)=>void;open:(v:View)=>void;close:()=>void}){
  const matches=(v:unknown)=>String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().includes(query.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase());
  const go=(v:View)=>{open(v);close()};
  const rows=[...nav.flatMap(s=>s.items).filter(i=>matches(i.label)).map(i=>({key:i.id,label:i.label,kind:"Recurso",view:i.id})),...ctx.boot.tasks.filter(t=>matches(t.title)).map(t=>({key:`t${t.id}`,label:t.title,kind:t.status==="concluida"?"Tarefa concluída":"Tarefa",view:"tasks" as View})),...ctx.boot.events.filter(e=>matches(e.title)).map(e=>({key:`e${e.id}`,label:e.title,kind:humanDate(e.event_date),view:"calendar" as View})),...ctx.boot.documents.filter(d=>matches(d.file_name)).map(d=>({key:`d${d.id}`,label:d.file_name,kind:"Documento",view:"documents" as View,url:`/api/planner?action=document&id=${d.id}`})),...ctx.boot.links.filter(l=>matches(l.title)).map(l=>({key:`l${l.id}`,label:l.title,kind:l.kind==="product"?"Produto favorito":"Atalho",view:"links" as View,url:l.url}))].slice(0,20) as Row[];
  return <div className="modal-backdrop command-backdrop" onClick={close}><section className="modal command-search" role="dialog" aria-modal="true" aria-label="Busca geral do Planner" onClick={e=>e.stopPropagation()}><header><h2>Buscar no Planner</h2><button onClick={close} aria-label="Fechar busca">×</button></header><input autoFocus aria-label="Pesquisar" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Tarefas, arquivos, agenda, favoritos..."/><div className="command-results">{rows.map(r=>r.url?<a key={r.key} href={r.url} target="_blank" rel="noreferrer"><span>{r.label}</span><small>{r.kind} ↗</small></a>:<button key={r.key} onClick={()=>go(r.view)}><span>{r.label}</span><small>{r.kind}</small></button>)}{!rows.length&&<p>Nenhum resultado para “{query}”.</p>}</div><footer><small>Esc fecha a busca · Tab navega pelos resultados</small></footer></section></div>;
}

function FocusTimer({visible,tasks}:{visible:boolean;tasks:Row[]}){
  const [duration,setDuration]=useState(25);const [seconds,setSeconds]=useState(25*60);const [deadline,setDeadline]=useState(0);const [target,setTarget]=useState("");const [done,setDone]=useState(false);
  useEffect(()=>{if(!deadline)return;const tick=()=>{const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));setSeconds(remaining);if(!remaining){setDeadline(0);setDone(true)}};tick();const timer=setInterval(tick,1000);return()=>clearInterval(timer)},[deadline]);
  const label=`${Math.floor(seconds/60).toString().padStart(2,"0")}:${(seconds%60).toString().padStart(2,"0")}`;
  return <section className="focus-strip panel" hidden={!visible&&!deadline}><div><small>{done?"SESSÃO CONCLUÍDA":"MODO FOCO"}</small><strong role="timer">{label}</strong></div><label>Objetivo<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Escolha uma tarefa ou foque livremente</option>{tasks.filter(t=>t.status!=="concluida").map(t=><option value={t.id} key={t.id}>{t.title}</option>)}</select></label><label>Duração<select value={duration} disabled={Boolean(deadline)} onChange={e=>{const n=Number(e.target.value);setDuration(n);setSeconds(n*60);setDone(false)}}><option value={25}>Foco · 25 min</option><option value={50}>Foco · 50 min</option><option value={5}>Pausa · 5 min</option><option value={15}>Pausa · 15 min</option></select></label><button className="primary" onClick={()=>{setDone(false);if(deadline){setSeconds(Math.max(0,Math.ceil((deadline-Date.now())/1000)));setDeadline(0)}else{const next=seconds||duration*60;setSeconds(next);setDeadline(Date.now()+next*1000)}}}>{deadline?"Pausar":"Iniciar"}</button><button onClick={()=>{setDeadline(0);setSeconds(duration*60);setDone(false)}}>Reiniciar</button>{done&&<span role="status">Sessão concluída. Faça uma pausa.</span>}</section>;
}
